// Fontes e limitações (#/evidencias) — design Evidence: what each badge means, every data source with
// checksums, the independent checks (PGDA, JPL Horizons) and the known limits. Read straight from data/.
// Source of truth: this .tsx file (Preact). evidencias.js is generated by `npm --prefix web run build:ts`.
// Kept imperative: the pgvector search result list is re-rendered by the submit handler, outside the first render.
import { h, Fragment, render as paint, type VNode } from "../../vendor/preact/preact.module.js";
import { num } from "../../ds/components.js";
import { buildHash, type RouteCtx } from "../../ds/router.js";
import { Badge, LayerCard, mount } from "../../ds/ui.js";
import { loadSites, type Provenance } from "../data.js";
// @ts-ignore TS7016: JS module without types
import { backendVectorAvailability, backendVectorSearch } from "../../lab/backend-bridge.js";

interface PgdaResult { site: string; diff_sun_pp: number; pipeline_mean_solar_disc_pct: number; pgda_avg_solar_disc_pct: number; pipeline_earth_centre_pct: number; pgda_avg_earth_any_part_pct: number; }
interface Pgda { results: PgdaResult[]; caveats: string[]; }
interface HorComparison { body: string; n: number; max_abs_el_diff_deg: number; max_abs_az_diff_deg_cos_el: number; }
interface Hor { results: { site: string; comparisons: HorComparison[] }[]; reference: string; }
interface VecHit { source_url?: string; title: string; similarity: number; sha256: string; }
interface VecStatus { enabled: boolean; available: boolean; modelID?: string; reason?: string; }

const getJSON = <T,>(url: string): Promise<T | null> => fetch(url).then(r => (r.ok ? (r.json() as Promise<T>) : null), () => null);
const short = (n: string) => n.replace(/\s*\(.*\)$/, "");
const link = (url?: string | null, text?: string): VNode => (url ? <a href={url} rel="noopener" target="_blank">{text || url}</a> : <span class="t3">N/D</span>);

export async function render(outlet: HTMLElement, ctx: RouteCtx): Promise<void> {
  const data = await loadSites();
  const [pgda, hor, meta, vecStatus] = await Promise.all([
    getJSON<Pgda>("./data/validation/validation_pgda.json"), getJSON<Hor>("./data/validation/validation_horizons.json"),
    getJSON<{ provenance?: Provenance }>("./data/" + data.sites[0].series + ".json"),
    backendVectorAvailability() as Promise<VecStatus>]);
  const prov = meta && meta.provenance;
  const siteName = (id: string) => short((data.sites.find(s => s.id === id) || { name: id }).name);

  let vecInput!: HTMLInputElement, vecResults!: HTMLElement;
  const onSearch = async (ev: Event) => {
    ev.preventDefault();
    const q = vecInput.value.trim();
    if (!q) return;
    paint(<p class="t2">Consultando pgvector…</p>, vecResults);
    try {
      const res = await backendVectorSearch(q, { limit: 4, modelID: vecStatus.modelID });
      if (!res.results.length) {
        paint(<p class="t2">Nenhuma fonte encontrada.</p>, vecResults);
        return;
      }
      paint(<>{(res.results as VecHit[]).map(hit => <p class="small">{link(hit.source_url, hit.title)}{` · ${(hit.similarity * 100).toFixed(0)}% · SHA ${hit.sha256.slice(0, 12)}…`}</p>)}</>, vecResults);
    } catch (err) {
      paint(<p class="t2">{(err as Error).message || "Busca indisponível."}</p>, vecResults);
    }
  };

  mount(outlet, <div class="ev stack">
    <div class="page-head"><div><p class="lbl-s">Evidências</p><h1 data-route-title="">Fontes e limitações</h1></div></div>
    <section class="solid card"><h2 class="h-card">Como ler os selos</h2>
      <dl class="seals">
        <dt><Badge kind="val" /></dt><dd>Produto oficial NASA/JPL usado como referência (ex.: PGDA, Horizons).</dd>
        <dt><Badge kind="est" /></dt><dd>Calculado por nós a partir de dado real (LOLA + SPICE). Prévio, não revisado pela NASA.</dd>
        <dt><Badge kind="sim" /></dt><dd>Simulação ou dado sintético (painel de bordo, laboratório de pouso).</dd>
        <dt><Badge kind="nd" /></dt><dd>Não disponível ou não calculado. Nunca mostramos 0 no lugar de um valor ausente.</dd>
      </dl></section>
    <div class="cards2">
      <LayerCard title="Comparação com NASA PGDA" badge="val"
        answer={pgda ? "Diferença de Sol entre " + num(Math.min(...pgda.results.map(r => r.diff_sun_pp)), 1) + " e " + num(Math.max(...pgda.results.map(r => r.diff_sun_pp)), 1) + " pontos percentuais nos " + pgda.results.length + " locais." : "N/D"}
        why={pgda ? <ul class="t2">{pgda.caveats.map(c => <li>{c}</li>)}</ul> : "Arquivo de validação indisponível."}
        proof={pgda ? pgda.results.map((r): [string, string] => [siteName(r.site),
          "Sol " + num(r.pipeline_mean_solar_disc_pct, 1) + "% vs " + num(r.pgda_avg_solar_disc_pct, 1) + "% · Terra " + num(r.pipeline_earth_centre_pct, 1) + "% vs " + num(r.pgda_avg_earth_any_part_pct, 1) + "%"]) : []} />
      <LayerCard title="Conferência com JPL Horizons" badge="val"
        answer={hor ? "Maior diferença de elevação: " + num(Math.max(...hor.results.flatMap(r => r.comparisons.map(c => c.max_abs_el_diff_deg))), 3) + "° em " + hor.results.reduce((n, r) => n + r.comparisons.reduce((m, c) => m + c.n, 0), 0) + " comparações." : "N/D"}
        why={hor ? "Datas espalhadas pela janela 2025–2028 conferidas com a API do JPL Horizons (" + hor.reference + ")." : "Arquivo de validação indisponível."}
        proof={hor ? hor.results.map((r): [string, string] => [siteName(r.site),
          r.comparisons.map(c => (c.body === "sun" ? "Sol" : "Terra") + " Δel " + num(c.max_abs_el_diff_deg, 3) + "°, Δaz·cos " + num(c.max_abs_az_diff_deg_cos_el, 3) + "°").join(" · ")]) : []} />
    </div>
    <section class="solid card"><h2 class="h-card">Busca semântica de fontes (pgvector)</h2>
      <p class="t2">{vecStatus.enabled && vecStatus.available
        ? `Índice ativo (${vecStatus.modelID || "384d"}) — somente metadados de proveniência, nunca física lunar.`
        : `Índice semântico ${vecStatus.enabled ? "indisponível" : "desativado"} no servidor (${vecStatus.reason || "offline"}).`}</p>
      {vecStatus.enabled && vecStatus.available ? <>
        <form class="row" onSubmit={onSearch}>
          <input type="search" placeholder="Ex.: LOLA DEM, SPICE, Malapert" aria-label="Buscar metadados de fontes" ref={(el: HTMLInputElement | null) => { if (el) vecInput = el; }} />
          <button type="submit" class="chipg">Buscar fontes</button></form>
        <div class="stack small" ref={(el: HTMLElement | null) => { if (el) vecResults = el; }} />
      </> : null}
    </section>
    <section class="solid card tablewrap"><h2 class="h-card">Fontes dos dados</h2>
      <table class="mtab"><thead><tr><th scope="col">Dado</th><th scope="col">Fonte</th><th scope="col">Verificação</th></tr></thead>
        <tbody>
          <tr><th scope="row">Relevo</th><td>{prov ? prov.terrain : "N/D"}</td><td class="mono small">{prov ? "SHA-256 " + prov.terrain_sha256.slice(0, 16) + "…" : "N/D"}</td></tr>
          {prov ? Object.entries(prov.kernel_sha256).map(([k, sha]) => <tr><th scope="row">Efeméride</th>
            <td>{link(prov.kernel_sources && prov.kernel_sources[k], k)}</td><td class="mono small">{"SHA-256 " + sha.slice(0, 16) + "…"}</td></tr>) : []}
          {data.sites.map(s => <tr><th scope="row">{short(s.name)}</th><td>{link(s.source_url, s.source)}</td>
            <td class="small">{num(s.lat, 2, "°") + ", " + num(s.lon, 2, "°") + " · centro de catálogo"}</td></tr>)}
        </tbody></table></section>
    <section class="solid card"><h2 class="h-card">Limitações</h2>
      <ul class="t2">
        <li>{"Status científico: " + data.raw.science_status + " (prévio, não validado de forma independente)."}</li>
        <li>{data.raw.note}</li>
        <li>Sol e Terra são pontos (centro do disco) contra o horizonte LOLA; sem refração, sem antena, sem rádio.</li>
        <li>Energia e bateria não são calculadas para locais reais (N/D). O painel de bordo usa um modelo sintético (SIM).</li>
        <li>O sombreado do mapa é ilustrativo (hillshade), não é simulação de iluminação.</li>
        <li>Sem recomendação de voo. A NASA não endossa esta ferramenta.</li>
      </ul>
      <p><a class="chipg" href={buildHash("/bordo/status", { site: ctx.site })}>Status do painel de bordo →</a></p></section>
  </div>);
}
